        boundary = cls._comparison_boundary_at(
            transition_index, before_state, after_state
        )
        return result(
            "continued",
            boundary,
            (),
            (isolated_segment(node) for node in after_nodes),
            cls._comparison_newly_rotated(
                before_state, after_state, requested
            ),
        )
